import{_ as t,o as e,c as r,a5 as i}from"./chunks/framework.BmD0ICqc.js";const u=JSON.parse('{"title":"同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる","description":"","frontmatter":{"title":"同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる","study":{"source":"新規執筆","section":"practice","format":"sample","status":"published","domain":"graphics","collection":"taau-observation","order":1,"summary":"384×216の同じ画面で、ネイティブ描画と192×108からの拡大を比べ、4フレームのサンプルで高解像度の画素を埋める。","aliases":["TAAUの実践","WebGL 2","アップスケーリング","バイリニア拡大","ジッタ","内部解像度","出力解像度"],"verification":"Yangらの論文とEpicのTAAU資料に照合（2026-11-13）"}},"headers":[],"relativePath":"practice/graphics/taau-observation.md","filePath":"practice/graphics/taau-observation.md"}'),s={name:"practice/graphics/taau-observation.md"};function o(l,a,n,c,d,h){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる" tabindex="-1">同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる <a class="header-anchor" href="#同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる" aria-label="Permalink to &quot;同じシーンでネイティブ描画・バイリニア・時間方向の拡大を比べる&quot;">​</a></h1><p>シーンを固定し、表示用の画像を384×216にそろえます。細い線や斜めの境界に注目すると、元の画素数と、履歴で得られたサンプルの違いを見比べられます。<a href="/study/graphics/postprocess/upscaling.html">アップスケーリングの記事</a>で、TAAからTAAUにつながる流れとDLSS・FSRの違いを図解しています。</p><p><a href="/study/samples/graphics/taau-observation/index.html" target="_self">3方式の比較デモを開く</a></p><h2 id="_3方式を切り替える" tabindex="-1">3方式を切り替える <a class="header-anchor" href="#_3方式を切り替える" aria-label="Permalink to &quot;3方式を切り替える&quot;">​</a></h2><table tabindex="0"><thead><tr><th>モード</th><th>1フレームで描く解像度</th><th>384×216の出力に使う色</th></tr></thead><tbody><tr><td>ネイティブ描画</td><td>384×216</td><td>出力格子で直接描いた色</td></tr><tr><td>バイリニア拡大</td><td>192×108</td><td>同じフレームの周囲の色を補間した結果</td></tr><tr><td>時間方向のアップスケーリング</td><td>192×108</td><td>フレームごとにずらして取得した色と、未取得の場所の補間色</td></tr></tbody></table><ol><li><strong>ネイティブ描画</strong>で、標識や手すりの細い線の見え方を覚えます。</li><li><strong>バイリニア拡大</strong>に切り替えます。細い線の境目や、色が混ざって見える場所を探します。</li><li><strong>時間方向のアップスケーリング</strong>を選び、<strong>自動で進める</strong>をオフにしてから、<strong>履歴をリセット</strong>します。<strong>1フレーム進める</strong>を押すたびに、2×2の取得済み位置が一つ増えます。4フレーム分がそろった後、ネイティブ描画へ戻って見比べます。</li></ol><h2 id="_4フレームで何がそろうか" tabindex="-1">4フレームで何がそろうか <a class="header-anchor" href="#_4フレームで何がそろうか" aria-label="Permalink to &quot;4フレームで何がそろうか&quot;">​</a></h2><p>192×108は縦横それぞれ384×216の半分です。低解像度で1回描くと、出力の2×2画素の範囲から1か所をサンプルします。次のフレームではサンプル位置をずらします。取得した色を出力格子の位置ごとに保存して、あとから描いた色で別の位置のサンプルを埋めていきます。</p><p>この実践は、静止したシーンと出力画素にぴったり合う4つの位置を使います。そのため4回の描画で、ネイティブと同じ場所の色がそろいます。履歴が有効な条件を固定した教材用の実装です。動くシーンでの再投影や履歴検証は、<a href="/study/practice/graphics/taa-observation.html">TAAの実践</a>で観察できます。DLSSやFSRの再構成は、製品と世代ごとのアルゴリズムで行います。</p><h2 id="理解度チェック" tabindex="-1">理解度チェック <a class="header-anchor" href="#理解度チェック" aria-label="Permalink to &quot;理解度チェック&quot;">​</a></h2><ol><li><p>時間方向のモードで、履歴をリセットしてすぐはなぜバイリニアに近く見えますか。</p><details class="details custom-block"><summary>解答</summary><p>出力の細かい位置のサンプルがまだそろっていないためです。実践では未取得の位置を一時的にバイリニア補間で埋め、サンプルを取れた位置から置き換えます。</p></details></li><li><p>1回目と同じ位置を繰り返し描くと、4フレーム後に出力の2×2画素はそろいますか。</p><details class="details custom-block"><summary>解答</summary><p>同じ点の色を取り続けるため、他の3点の色は取得できません。フレームごとに位置をずらすことで、出力の異なる画素を埋められます。</p></details></li></ol><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/study/graphics/postprocess/upscaling.html">アップスケーリング</a>で、TAAUと製品ごとの再構成方法を整理する。</li><li><a href="/study/graphics/postprocess/taa.html">TAA</a>で、ジッタ、再投影、履歴検証の役割を確認する。</li><li><a href="/study/learn/roadmap.html?node=gfx-postprocess#graphics">3DCG・描画ロードマップの「ポストプロセスとAA」</a></li></ul><h2 id="参考資料" tabindex="-1">参考資料 <a class="header-anchor" href="#参考資料" aria-label="Permalink to &quot;参考資料&quot;">​</a></h2><ul><li><a href="https://diglib.eg.org/items/cfa6a05c-53b3-4ee1-979d-48abc6225f6b" target="_blank" rel="noreferrer">Lei Yang, Shiqiu Liu, Marco Salvi — A Survey of Temporal Antialiasing Techniques</a></li><li><a href="https://dev.epicgames.com/documentation/en-us/unreal-engine/screen-percentage-with-temporal-upscale-in-unreal-engine?application_version=5.8" target="_blank" rel="noreferrer">Epic — Screen Percentage with Temporal Upscale（Unreal Engine 5.8）</a></li></ul>',15)])])}const m=t(s,[["render",o]]);export{u as __pageData,m as default};
